import React, { useState } from 'react';
import { SliderSkeleton } from '.';
import Slider from './Slider';
import { Layer } from '../Layer';
import mdx from './Slider.mdx';

export default {
  title: 'Components/Slider',
  component: Slider,
  subcomponents: {
    SliderSkeleton,
  },
  parameters: {
    docs: {
      page: mdx,
    },
  },
};

export const Default = () => (
  <Slider
    labelText="Slider Label"
    value={50}
    min={0}
    max={100}
    step={1}
    stepMultiplier={10}
    noValidate
  />
);

export const ControlledSlider = () => {
  const [val, setVal] = useState(87);
  return (
    <>
      <button
        type="button"
        onClick={() => setVal(Math.round(Math.random() * 100))}>
        randomize value
      </button>
      <Slider
        max={100}
        min={0}
        value={val}
        onChange={({ value }) => setVal(value)}
      />
      <h1>{val}</h1>
    </>
  );
};

export const WithLayer = () => {
  return (
    <>
      <Slider
        labelText="First Layer"
        value={50}
        min={0}
        max={100}
        step={1}
        stepMultiplier={10}
        noValidate
      />
      <Layer>
        <Slider
          labelText="Second Layer"
          value={50}
          min={0}
          max={100}
          step={1}
          stepMultiplier={10}
          noValidate
        />
        <Layer>
          <Slider
            labelText="Third Layer"
            value={50}
            min={0}
            max={100}
            step={1}
            stepMultiplier={10}
            noValidate
          />
        </Layer>
      </Layer>
    </>
  );
};

